package com.callguard;
import android.content.SharedPreferences;import org.json.*;import java.util.*;import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;
final class BackupData {
    private static boolean permitted(String key){return Arrays.asList("rule","media","recordOnly","profile").contains(key)||key.matches("profile_(custom|work|sleep|meeting)_(rule|media|scheduled|days|start|end|initialized)");}
    static JSONObject export(Store store) throws JSONException {JSONObject result=new JSONObject().put("version",1);JSONArray contacts=new JSONArray();for(Rules.Contact c:store.contacts())contacts.put(new JSONObject().put("name",c.name).put("number",c.number).put("white",c.white));JSONObject settings=new JSONObject();for(Map.Entry<String,?> entry:store.prefs().getAll().entrySet())if(permitted(entry.getKey()))settings.put(entry.getKey(),entry.getValue());JSONArray history=new JSONArray();try(android.database.Cursor cursor=store.history()){while(cursor.moveToNext())history.put(new JSONObject().put("caller",cursor.getString(1)).put("video",cursor.getInt(2)==1).put("result",cursor.getString(3)).put("at",cursor.getLong(4)).put("number",cursor.getString(5)));}return result.put("contacts",contacts).put("settings",settings).put("history",history);}
    static void restore(Store store,JSONObject value) throws Exception {
        if(value.getInt("version")!=1)throw new IllegalArgumentException("Desteklenmeyen yedek.");JSONArray contacts=value.getJSONArray("contacts");if(contacts.length()>5000)throw new IllegalArgumentException("Yedek çok büyük.");List<ContentValues> rows=new ArrayList<>();Set<String> seen=new HashSet<>();
        for(int i=0;i<contacts.length();i++){JSONObject c=contacts.getJSONObject(i);String name=c.getString("name"),number=Rules.number(c.getString("number"));if(name.length()>200||number.isEmpty()||!seen.add(number))throw new IllegalArgumentException("Yedekte geçersiz veya yinelenen kişi var.");ContentValues row=new ContentValues();row.put("name",name);row.put("number",number);row.put("white",c.getBoolean("white")?1:0);rows.add(row);}
        JSONObject settings=value.getJSONObject("settings");Map<String,Object> accepted=new HashMap<>();Iterator<String> keys=settings.keys();while(keys.hasNext()){String key=keys.next();if(!permitted(key))continue;Object v=settings.get(key);String tail=key.replaceFirst("^profile_(custom|work|sleep|meeting)_","");if(tail.equals("rule"))Rules.Mode.valueOf((String)v);else if(tail.equals("media"))Rules.Media.valueOf((String)v);else if(tail.equals("profile")){if(!Arrays.asList("custom","work","sleep","meeting").contains(v))throw new IllegalArgumentException("Geçersiz profil.");}else if(Arrays.asList("days","start","end").contains(tail)){if(!(v instanceof Number))throw new IllegalArgumentException("Geçersiz saat.");int n=((Number)v).intValue();if(n<0||n>(tail.equals("days")?127:1439))throw new IllegalArgumentException("Geçersiz saat.");v=n;}else if(!(v instanceof Boolean))throw new IllegalArgumentException("Geçersiz ayar.");accepted.put(key,v);}
        JSONArray history=value.optJSONArray("history");List<ContentValues> historyRows=new ArrayList<>();if(history!=null){if(history.length()>500)throw new IllegalArgumentException("Geçmiş çok büyük.");for(int i=0;i<history.length();i++){JSONObject entry=history.getJSONObject(i);String caller=entry.getString("caller"),result=entry.getString("result"),number=entry.getString("number");if(caller.length()>200||result.length()>200||(!number.isEmpty()&&Rules.number(number).isEmpty())||entry.getLong("at")<0)throw new IllegalArgumentException("Geçersiz arama kaydı.");ContentValues row=new ContentValues();row.put("caller",caller);row.put("result",result);row.put("video",entry.getBoolean("video")?1:0);row.put("at",entry.getLong("at"));row.put("number",number);historyRows.add(row);}}
        SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{db.delete("contacts",null,null);for(ContentValues row:rows)db.insertOrThrow("contacts",null,row);db.delete("history",null,null);for(ContentValues row:historyRows)db.insertOrThrow("history",null,row);db.setTransactionSuccessful();}finally{db.endTransaction();}
        SharedPreferences.Editor editor=store.prefs().edit();for(String key:store.prefs().getAll().keySet())if(permitted(key))editor.remove(key);for(Map.Entry<String,Object> e:accepted.entrySet()){Object v=e.getValue();if(v instanceof Boolean)editor.putBoolean(e.getKey(),(Boolean)v);else if(v instanceof Integer)editor.putInt(e.getKey(),(Integer)v);else editor.putString(e.getKey(),String.valueOf(v));}editor.putBoolean("enabled",false).apply();store.setting("enabled",false);
    }
    private BackupData(){}
}
